 (!view?'<div class="entry"><button class="btn btn-sm" data-entry-mode="analysis" type="button" aria-pressed="'+(state.entryMode!=='requirements')+'">直接开始分析</button><button class="btn btn-sm" data-entry-mode="requirements" type="button" aria-pressed="'+(state.entryMode==='requirements')+'">先帮我理清需求</button><button class="btn btn-sm" data-action="requirement-edit" type="button">自己写下需求</button></div>':'<nav class="viewtabs" aria-label="任务视图">'+[['conversation','对话'],['results','成果'],['evidence','依据']].map(([id,l])=>'<button data-view="'+id+'" type="button" aria-current="'+(page===id?'page':'false')+'">'+l+'</button>').join('')+'</nav>')+
 decisionAssociation(view)+(pro?stages(state):'')+(home?'':versionSelection(view,state.readonly||state.pending)+assetBadge(view))+
 '<div class="reading-layout'+((page==='results'||state.expanded==='report')&&!home?' with-assistant':'')+'"><div class="thread" data-scroll="reading">'+(home?'':(state.expanded?'<button class="btn btn-sm" data-action="back" type="button">返回对话</button>':'')+content)+'</div><aside class="same-task-assistant" aria-label="同任务助手">'+(!home&&page==='results'?'<h2>同任务助手</h2><p class="fine">与对话共用上下文、草稿和引用</p>':'')+composer(state,view)+'</aside></div>'+
 (home?'<div class="startergrid"><button class="starter" data-starter="经营变化" type="button"><strong>经营变化，从哪里看起？</strong><span class="fine">比较期间与分组，寻找有依据的变化线索</span></button><button class="starter" data-starter="会员复购" type="button"><strong>什么影响了会员复购？</strong><span class="fine">明确对象与范围，保留假设和证据的区别</span></button></div></section>':'')+'</div></main><div class="pane-divider" role="separator" tabindex="0" aria-orientation="vertical" data-resize="right" aria-label="调整检查详情宽度"'+(state.drawer?'':' hidden')+'></div><aside class="drawer" id="analysis-drawer" aria-label="当前分析检查详情"'+(state.drawer?'':' hidden')+'><header class="drawer-head"><strong>依据与详情</strong><button class="btn btn-sm" data-action="drawer-close" type="button">关闭</button></header><nav class="inspector-groups" aria-label="检查器分组">'+[['evidence','证据'],['assets','口径与资产'],['process','过程']].map(([id,l])=>'<button class="btn btn-sm'+(group===id?' active':'')+'" type="button" data-detail="'+({evidence:'evidence',assets:'context',process:'execution'})[id]+'">'+l+'</button>').join('')+'</nav><div class="detail-tabs" role="tablist" aria-label="详情分类">'+tabs.filter(([id])=>group==='assets'?['context','files'].includes(id):group==='process'?['plan','execution'].includes(id):id==='evidence').map(([id,l])=>'<button id="detail-'+id+'" role="tab" aria-controls="analysis-detail-content" aria-selected="'+(tab===id)+'" tabindex="'+(tab===id?0:-1)+'" type="button" data-detail="'+id+'">'+l+'</button>').join('')+'</div><div class="detail-content" data-scroll="inspector" id="analysis-detail-content" role="tabpanel" tabindex="0" aria-label="分析详情">'+detail(view,tab,state.previewMaterials,state.nativeSession)+'</div></aside></div></div>';
